    );
    assert.isFalse(yield* Effect.promise(check));
    allowed = true;
    assert.isTrue(yield* Effect.promise(check));
    yield* fs.remove(jar);
    assert.isFalse(yield* Effect.promise(check));
  }).pipe(Effect.provide(NodeServices.layer), Effect.scoped),
);

