import { PrismaApiError, type PrismaManagementClient } from "@/Prisma/Client";
import {
  startDeploymentIdempotent,
  stopDeploymentIdempotent,
} from "@/Prisma/Internal/DeploymentActions";
import { describe, expect, it } from "alchemy-test";
import * as Effect from "effect/Effect";
import {
  type Captured,
  dispatchTo,
  makeFakeManagementApi,
  unhandled,
} from "./fixtures/FakeManagementApi.ts";

const conflict = (action: "start" | "stop") =>
  new PrismaApiError({
    method: "POST",
    path: `/v1/deployments/deployment-1/${action}`,
    status: 409,
    message: "state conflict",
  });

const version = (status: string) => ({
  id: "deployment-1",
  type: "deployment" as const,
  serviceId: "service-1",
  url: "https://api.prisma.test/v1/deployments/deployment-1",
  foundryVersionId: "foundry-1",
  status,
  previewDomain: null,
  createdAt: "2026-01-01T00:00:00Z",
});

/**
 * Serve the Management API from the same hermetic client-shaped handlers
 * these tests declare, for the deployment routes the actions now reach
 * through distilled operations. An injected `PrismaApiError` becomes its
 * real status, `undefined` becomes a 404, everything else a `{ data }`
 * envelope.
 */
const clientBackedApi = (client: any) =>
  makeFakeManagementApi((request: Captured) => {
    // segments[0] is the "v1" prefix.
    const [head, id, tail] = request.pathname
      .split("/")
      .filter((segment) => segment.length > 0)
      .slice(1);
    const { call, callVoid } = dispatchTo(request);

    if (head === "deployments" && id !== undefined) {
      if (tail === "start") return call(client.startDeployment, [id]);
      if (tail === "stop") return callVoid(client.stopDeployment, [id]);
      if (request.method === "GET") return call(client.getDeployment, [id]);
    }
    return unhandled(request);
  });

describe("Prisma deployment actions", () => {
  it.effect("does not hide a start conflict for an unuploaded version", () => {
    const error = conflict("start");
    const client = {
      startDeployment: () => Effect.fail(error),
      getDeployment: () => Effect.succeed(version("new")),
    } as unknown as PrismaManagementClient;

    return Effect.gen(function* () {
      const observed = yield* startDeploymentIdempotent("deployment-1").pipe(
        Effect.flip,
      );
      // Over the wire the injected conflict decodes into the typed error.
      expect(observed._tag).toBe("Conflict");
      expect(observed.message).toBe("state conflict");
    }).pipe(Effect.provide(clientBackedApi(client).layer));
  });

  it.effect("accepts a start conflict only after observing progress", () => {
    const client = {
      startDeployment: () => Effect.fail(conflict("start")),
      getDeployment: () => Effect.succeed(version("provisioning")),
    } as unknown as PrismaManagementClient;

    return startDeploymentIdempotent("deployment-1").pipe(
      Effect.provide(clientBackedApi(client).layer),
    );
  });

  it.effect(
    "accepts a stop conflict while teardown is already progressing",
    () => {
      const client = {
        stopDeployment: () => Effect.fail(conflict("stop")),
        getDeployment: () => Effect.succeed(version("stopping")),
      } as unknown as PrismaManagementClient;

      return stopDeploymentIdempotent("deployment-1").pipe(
        Effect.provide(clientBackedApi(client).layer),
      );
    },
  );
});

import { assert, describe, it } from "@effect/vitest"
import { Effect, Encoding, Redacted } from "effect"
import { HttpClientRequest, HttpServerRequest } from "effect/unstable/http"
import { HttpApiBuilder, HttpApiSecurity } from "effect/unstable/httpapi"

const decode = <Security extends HttpApiSecurity.HttpApiSecurity>(authorization: string, security: Security) =>
  HttpApiBuilder.securityDecode(security).pipe(
    Effect.provideService(
      HttpServerRequest.HttpServerRequest,
      HttpServerRequest.fromWeb(new Request("http://localhost/", { headers: { authorization } }))
    ),
    Effect.provideService(HttpServerRequest.ParsedSearchParams, {})
  )

describe("HttpApiSecurity", () => {
  describe("securityDecode", () => {
    it.effect("decodes a bearer token without a leading space", () =>
      Effect.gen(function*() {
        const token = "abc123"
        const { headers } = HttpClientRequest.get("http://localhost/").pipe(
          HttpClientRequest.bearerToken(token)
        )
        const credential = yield* HttpApiBuilder.securityDecode(HttpApiSecurity.bearer).pipe(
          Effect.provideService(
            HttpServerRequest.HttpServerRequest,
            HttpServerRequest.fromWeb(new Request("http://localhost/", { headers }))
          ),
          Effect.provideService(HttpServerRequest.ParsedSearchParams, {})
        )

        assert.strictEqual(Redacted.value(credential), token)
      }))

    it.effect("decodes a custom http scheme without a leading space", () =>
      Effect.gen(function*() {
        const credential = yield* decode("Token abc123", HttpApiSecurity.http({ scheme: "Token" }))

        assert.strictEqual(Redacted.value(credential), "abc123")
      }))

    it.effect("matches HTTP schemes case-insensitively", () =>
      Effect.gen(function*() {
        const credential = yield* decode("bEaReR abc123", HttpApiSecurity.bearer)

        assert.strictEqual(Redacted.value(credential), "abc123")
      }))

    it.effect("accepts multiple spaces before HTTP credentials", () =>
      Effect.gen(function*() {
        const credential = yield* decode("Bearer   abc123", HttpApiSecurity.bearer)

        assert.strictEqual(Redacted.value(credential), "abc123")
      }))

    it.effect("rejects mismatched and malformed HTTP schemes", () =>
      Effect.gen(function*() {
        const mismatched = yield* decode("Basic abc123", HttpApiSecurity.bearer)
        const malformed = yield* decode("Bearerabc123", HttpApiSecurity.bearer)

        assert.strictEqual(Redacted.value(mismatched), "")
        assert.strictEqual(Redacted.value(malformed), "")
      }))

    it.effect("decodes Basic credentials using the first colon separator", () =>
      Effect.gen(function*() {
        const encoded = Encoding.encodeBase64("alice:secret:with:colons")
        const credential = yield* decode(`Basic ${encoded}`, HttpApiSecurity.basic)

        assert.strictEqual(credential.username, "alice")
        assert.strictEqual(Redacted.value(credential.password), "secret:with:colons")
      }))

    it.effect("rejects Basic credentials from a different scheme", () =>
      Effect.gen(function*() {
        const encoded = Encoding.encodeBase64("alice:secret")
        const credential = yield* decode(`Bearer ${encoded}`, HttpApiSecurity.basic)

        assert.strictEqual(credential.username, "")
        assert.strictEqual(Redacted.value(credential.password), "")
      }))
  })
})

