import * as AWS from "@/AWS";
import * as Test from "@/Test/Alchemy";
import * as agw2 from "@distilled.cloud/aws/apigatewayv2";
import { expect } from "alchemy-test";
import * as Effect from "effect/Effect";

const { test } = Test.make({ providers: AWS.providers() });

// CreateAuthorizer validates that the issuer serves a live
// `/.well-known/openid-configuration` discovery document (probed:
// BadRequestException "Issuer must have a valid discovery endpoint" for
// placeholder domains). Tokens are only validated at request time, so any
// stable public OIDC issuer exercises the CRUD lifecycle.
const ISSUER = "https://accounts.google.com";

test.provider(
  "create, update, delete JWT authorizer",
  (stack) =>
    Effect.gen(function* () {
      yield* stack.destroy();

      const deployAuthorizer = (audience: string[]) =>
        stack.deploy(
          Effect.gen(function* () {
            const api = yield* AWS.ApiGatewayV2.Api("AuthApi", {});
            const authorizer = yield* AWS.ApiGatewayV2.Authorizer(
              "JwtAuthorizer",
              {
                api,
                authorizerType: "JWT",
                identitySource: ["$request.header.Authorization"],
                jwtConfiguration: {
                  Issuer: ISSUER,
                  Audience: audience,
                },
              },
            );
            return {
              apiId: api.apiId,
              authorizerId: authorizer.authorizerId,
              name: authorizer.name,
            };
          }),
        );

      const out = yield* deployAuthorizer(["aud-1"]);
      expect(out.authorizerId).toBeTruthy();

      // Out-of-band verification via distilled.
      const remote = yield* agw2.getAuthorizer({
        ApiId: out.apiId,
        AuthorizerId: out.authorizerId,
      });
      expect(remote.AuthorizerType).toBe("JWT");
      expect(remote.JwtConfiguration?.Issuer).toBe(ISSUER);
      expect(remote.JwtConfiguration?.Audience).toEqual(["aud-1"]);

      // Update the audience in place (same authorizerId).
      const updated = yield* deployAuthorizer(["aud-1", "aud-2"]);
      expect(updated.authorizerId).toBe(out.authorizerId);

      const afterUpdate = yield* agw2.getAuthorizer({
        ApiId: out.apiId,
        AuthorizerId: out.authorizerId,
      });
      expect(afterUpdate.JwtConfiguration?.Audience).toEqual([
        "aud-1",
        "aud-2",
      ]);

      yield* stack.destroy();

      const gone = yield* agw2
        .getAuthorizer({
          ApiId: out.apiId,
          AuthorizerId: out.authorizerId,
        })
        .pipe(
          Effect.map(() => "still-exists" as const),
          Effect.catchTag("NotFoundException", () =>
            Effect.succeed("deleted" as const),
          ),
        );
      expect(gone).toBe("deleted");
    }),
  { timeout: 240_000 },
);

import * as AWS from "@/AWS";
import { SecurityConfig } from "@/AWS/OpenSearchServerless";
import * as Test from "@/Test/Alchemy";
import * as aoss from "@distilled.cloud/aws/opensearchserverless";
import { expect } from "alchemy-test";
import * as Effect from "effect/Effect";
import * as Schedule from "effect/Schedule";

const { test } = Test.make({ providers: AWS.providers() });

const CONFIG_NAME = "alchemy-test-saml";

// Self-signed X.509 certificate generated once with openssl and checked in as
// a constant (per the fixture convention — never generated at test time).
const SAML_CERT =
  "";

const SAML_METADATA = `<?xml version="1.0" encoding="UTF-8"?>
<md:EntityDescriptor xmlns:md="urn:oasis:names:tc:SAML:2.0:metadata" entityID="https://alchemy-test-idp.example.com/saml">
  <md:IDPSSODescriptor WantAuthnRequestsSigned="false" protocolSupportEnumeration="urn:oasis:names:tc:SAML:2.0:protocol">
    <md:KeyDescriptor use="signing">
      <ds:KeyInfo xmlns:ds="http://www.w3.org/2000/09/xmldsig#">
        <ds:X509Data>
          <ds:X509Certificate>${SAML_CERT}</ds:X509Certificate>
        </ds:X509Data>
      </ds:KeyInfo>
    </md:KeyDescriptor>
    <md:NameIDFormat>urn:oasis:names:tc:SAML:2.0:nameid-format:transient</md:NameIDFormat>
    <md:SingleSignOnService Binding="urn:oasis:names:tc:SAML:2.0:bindings:HTTP-Redirect" Location="https://alchemy-test-idp.example.com/sso"/>
    <md:SingleSignOnService Binding="urn:oasis:names:tc:SAML:2.0:bindings:HTTP-POST" Location="https://alchemy-test-idp.example.com/sso"/>
  </md:IDPSSODescriptor>
</md:EntityDescriptor>`;

const assertGone = (configId: string) =>
  aoss.getSecurityConfig({ id: configId }).pipe(
    Effect.flip,
    Effect.map((e) => expect(e._tag).toBe("ResourceNotFoundException")),
    Effect.retry({
      schedule: Schedule.max([Schedule.fixed("2 seconds"), Schedule.recurs(5)]),
    }),
  );

// Security configs are free and provision instantly, so the full lifecycle
// runs ungated: create a SAML config (with a Duration-typed sessionTimeout),
// no-op, update the description (config version bump), destroy, verify gone.
test.provider(
  "saml security config lifecycle: create, no-op, update, destroy, verify gone",
  (stack) =>
    Effect.gen(function* () {
      // Clean slate in case a previous run died mid-flight.
      yield* stack.destroy();

      const deployConfig = (
        description: string,
        sessionTimeout: "2 hours" | "3 hours" = "2 hours",
      ) =>
        stack.deploy(
          Effect.gen(function* () {
            const config = yield* SecurityConfig("Saml", {
              configName: CONFIG_NAME,
              type: "saml",
              description,
              samlOptions: {
                metadata: SAML_METADATA,
                groupAttribute: "groups",
                // Duration.Input — converted to wire minutes.
                sessionTimeout,
              },
            });
            return { config };
          }),
        );

      // Create.
      const created = yield* deployConfig("alchemy test saml config");
      expect(created.config.configName).toBe(CONFIG_NAME);
      expect(created.config.type).toBe("saml");
      expect(created.config.configId).toContain(`saml/`);
      expect(created.config.configId).toContain(`/${CONFIG_NAME}`);
      const initialVersion = created.config.configVersion;

      // Out-of-band verification via distilled — including the wire unit of
      // the Duration-typed sessionTimeout (minutes).
      const observed = yield* aoss.getSecurityConfig({
        id: created.config.configId,
      });
      expect(observed.securityConfigDetail?.type).toBe("saml");
      expect(observed.securityConfigDetail?.samlOptions?.sessionTimeout).toBe(
        120,
      );
      expect(observed.securityConfigDetail?.samlOptions?.groupAttribute).toBe(
        "groups",
      );

      // No-op redeploy: version must not change.
      const noop = yield* deployConfig("alchemy test saml config");
      expect(noop.config.configVersion).toBe(initialVersion);

      // Update the SAML session timeout (a samlOptions change is what bumps
      // the config version — description-only updates keep it, verified
      // against the live API) and the description.
      const updated = yield* deployConfig(
        "alchemy test saml config v2",
        "3 hours",
      );
      expect(updated.config.configVersion).not.toBe(initialVersion);
      expect(updated.config.description).toBe("alchemy test saml config v2");
      const observedUpdated = yield* aoss.getSecurityConfig({
        id: updated.config.configId,
      });
      expect(
        observedUpdated.securityConfigDetail?.samlOptions?.sessionTimeout,
      ).toBe(180);

      // Destroy and verify deletion out-of-band.
      const configId = created.config.configId;
      yield* stack.destroy();
      yield* assertGone(configId);
    }),
  { timeout: 120_000 },
);

import * as agw2 from "@distilled.cloud/aws/apigatewayv2";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Output from "../../Output.ts";
import { registerApiGatewayV2Binding } from "./BindingHttp.ts";
import { ResetAuthorizersCache } from "./ResetAuthorizersCache.ts";
import type { ApiGatewayV2Stage } from "./Stage.ts";

/**
 * HTTP implementation of the {@link ResetAuthorizersCache} binding.
 * Grants `apigateway:DELETE` on the stage's `/cache/authorizers` path and
 * calls the API with the host Function's credentials.
 */
export const ResetAuthorizersCacheHttp = Layer.effect(
  ResetAuthorizersCache,
  Effect.gen(function* () {
    const resetAuthorizersCache = yield* agw2.resetAuthorizersCache;
    return Effect.fn(function* <S extends ApiGatewayV2Stage>(stage: S) {
      const ApiId = yield* stage.apiId;
      const StageName = yield* stage.stageName;
      yield* registerApiGatewayV2Binding({
        cap: "AWS.ApiGatewayV2.ResetAuthorizersCache",
        target: stage,
        verb: "DELETE",
        paths: (region) => [
          Output.interpolate`arn:aws:apigateway:${region}::/apis/${stage.apiId}/stages/${stage.stageName}/cache/authorizers`,
        ],
      });
      return Effect.fn(
        `AWS.ApiGatewayV2.ResetAuthorizersCache(${stage.LogicalId})`,
      )(function* () {
        return yield* resetAuthorizersCache({
          ApiId: yield* ApiId,
          StageName: yield* StageName,
        });
      });
    });
  }),
);

import * as ag from "@distilled.cloud/aws/api-gateway";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Output from "../../Output.ts";
import { registerApiGatewayBinding } from "./BindingHttp.ts";
import { FlushStageAuthorizersCache } from "./FlushStageAuthorizersCache.ts";
import type { ApiGatewayStage } from "./Stage.ts";

/**
 * HTTP implementation of the {@link FlushStageAuthorizersCache} binding.
 * Grants `apigateway:DELETE` on the stage's `/cache/authorizers` path and
 * calls the API with the host Function's credentials.
 */
export const FlushStageAuthorizersCacheHttp = Layer.effect(
  FlushStageAuthorizersCache,
  Effect.gen(function* () {
    const flushStageAuthorizersCache = yield* ag.flushStageAuthorizersCache;
    return Effect.fn(function* <S extends ApiGatewayStage>(stage: S) {
      const RestApiId = yield* stage.restApiId;
      const StageName = yield* stage.stageName;
      yield* registerApiGatewayBinding({
        cap: "AWS.ApiGateway.FlushStageAuthorizersCache",
        target: stage,
        verb: "DELETE",
        paths: (region) => [
          Output.interpolate`arn:aws:apigateway:${region}::/restapis/${stage.restApiId}/stages/${stage.stageName}/cache/authorizers`,
        ],
      });
      return Effect.fn(
        `AWS.ApiGateway.FlushStageAuthorizersCache(${stage.LogicalId})`,
      )(function* () {
        return yield* flushStageAuthorizersCache({
          restApiId: yield* RestApiId,
          stageName: yield* StageName,
        });
      });
    });
  }),
);
